// ---- site (plan.md SITE, OPENINGS, ROOMS; all inclusive [x0,y0,z0,x1,y1,z1] or per-axis) ----------------------------
export const SITE = { x: [0, 43], y: [0, 17], z: [0, 31] };
export const ENTRANCE = [16, 2, 8];
export const MAIN = { x0: 2, z0: 11, x1: 29, z1: 25, yFloor: 1, yCeil: 9 };
